  "ทุกคำถามที่ถาม Nock · คำถามที่มีคำตอบจากทีม = คลังความรู้ที่ Nock ใช้ตอบคนต่อไป · ตอบได้หลายคน แก้ได้เฉพาะคำตอบของตัวเอง · โหวตขึ้น / ลง เลือกว่า Nock ใช้คำตอบไหน · คำถามที่ Nock ตอบไม่ได้รอ Super Admin / Director / Area Manager / Manager ตอบ": { en: "Every question asked to Nock · questions with a team answer = knowledge Nock uses for the next person · several people can answer, each edits only their own · vote up / down to pick which answer Nock uses · questions Nock couldn't answer wait for a Super Admin / Director / Area Manager / Manager", ja: "Nockへのすべての質問 · チームの回答がある質問 = Nockが次の人に使うナレッジ · 複数人が回答可、編集は自分の回答のみ · 賛成/反対でNockが使う回答を選択 · Nockが答えられない質問はSuper Admin/Director/Area Manager/Managerの回答待ち" },
