  "จบ": { en: "Ends", ja: "終了" },
  "จำนวนนักเรียนสูงสุดของคอร์สนี้ (รวมทุกคลาส) · นับคนที่แพ็กเกจยังไม่หมด · เต็มแล้วเลือกคอร์สนี้ในใบแจ้งหนี้ให้นักเรียนใหม่ไม่ได้ (ต่ออายุได้) · ว่าง = ไม่จำกัด": { en: "Most students this course takes (all classes) · counts people whose package hasn't ended · when full, new students can't pick it on an invoice (renewals can) · blank = no limit", ja: "このコースの定員（全クラス合計）· パッケージ有効中の人数 · 満員時は新規生徒を請求書で選択不可（継続は可）· 空欄 = 無制限" },
  "ซื้อเป็นชั่วโมง หักตามความยาวคาบจริง (24 ชม. ที่คาบ 2 ชม. = 12 คาบ, คาบ 90 นาที = 16 คาบ)": { en: "Bought in hours, charged by the real session length (24 hrs at 2-hr sessions = 12 sessions, 90-min sessions = 16)", ja: "時間単位で購入、実際の授業時間で消化（24時間・2時間授業 = 12回、90分授業 = 16回）" },
  "ซื้อเป็นสัปดาห์ นับจากวันเริ่ม เรียนกี่คาบก็ได้ในช่วงนั้น": { en: "Bought in weeks from the start date, any number of sessions in that time", ja: "開始日から週単位で購入、期間中は何回でも受講可" },
  "ดึงจากตารางราคาของสาขาตามระดับชั้นที่เลือก · แก้เป็นราคาพิเศษได้ (ต้องใส่เหตุผล)": { en: "Taken from the branch price chart for the chosen grades · can be changed to a special price (needs a reason)", ja: "選択した学年の校舎価格表から取得 · 特別価格に変更可（理由が必要）" },
  "ถ้ายังรวมคอร์ส ให้ใส่ราคาเดียวที่จะเก็บด้านล่าง": { en: "If you still combine them, enter the single price to charge below", ja: "まとめる場合は、下に請求する単一価格を入力" },
