  "พิมพ์แทน Memo ของแบรนด์ เฉพาะใบที่มีคอร์สของช่วงนี้ (คอร์สที่ผูกกับช่วงนี้ หรือคลาสพิเศษของช่วงนี้) — ออกใบก่อนช่วงเริ่มก็ใช้ Memo นี้ · เว้นว่าง = ใช้ Memo ของแบรนด์": { en: "Replaces the brand Memo, only on invoices with this period's courses (courses linked to the period, or its special classes) — invoices issued before the period starts use it too · blank = the brand Memo", ja: "この期間のコース（期間に紐づくコースまたは特別クラス）を含む請求書のみブランドのメモを置き換え — 期間開始前に発行する請求書にも適用 · 空欄 = ブランドのメモ" },
