  "ลาหลายวัน": { en: "Leave for several days", ja: "複数日のお休み" },
  "วันหยุดบริษัท: Settings › ระบบ › วันหยุด · วันหยุดของสาขา: Settings › สาขา › เวลาเปิด-ปิด & วันหยุด (เลือกเปิดทำการในวันหยุดบริษัทได้)": { en: "Company holidays: Settings › System › Holidays · branch holidays: Settings › Branch › Opening hours & holidays (a branch can choose to open on company holidays)", ja: "会社の休日：設定 › システム › 休日 · 校舎の休日：設定 › 校舎 › 営業時間と休日（会社の休日に開校も選択可）" },
  "วิชาเป็นรายการกลางของทุกสาขา: Settings › ระบบ › วิชา → พิมพ์ชื่อวิชาใหม่ เลือกสี แล้วกด เพิ่ม · จากนั้นแต่ละสาขาเลือกวิชาที่เปิดสอนที่ Settings › สาขา › วิชา": { en: "Subjects are one list for every branch: Settings › System › Subjects → type the new subject, pick a colour, then Add · then each branch picks its subjects in Settings › Branch › Subjects", ja: "科目は全校舎共通の一覧：設定 › システム › 科目 → 新しい科目名を入力、色を選んで追加 · 各校舎は設定 › 校舎 › 科目で開講科目を選択" },
  "สถิติ": { en: "Statistics", ja: "統計" },
  "สรุปการเรียน › กดแถวคาบ → เขียนสรุปของนักเรียน → ส่งไป Approve · คนอนุมัติต้องไม่ใช่คนเขียน แล้วจึงส่งผู้ปกครอง": { en: "Lesson summaries › click a session row → write each student's summary → send for approval · the approver must not be the writer, then it goes to parents", ja: "学習まとめ › 授業の行をクリック → 生徒のまとめを作成 → 承認依頼 · 承認者は作成者以外、その後保護者へ送信" },
  "สรุปการเรียน › การ์ด รอส่งไป Approve → อนุมัติ (หรือเปิดแถวเพื่อขอแก้) → ส่งผู้ปกครอง": { en: "Lesson summaries › the \"Waiting for approval\" card → approve (or open the row to request changes) → send to parents", ja: "学習まとめ ›「承認依頼待ち」カード → 承認（または行を開いて修正依頼）→ 保護者へ送信" },
  "สร้างนักเรียน": { en: "Create student", ja: "生徒を作成" },
  "สลับสาขา": { en: "Switch branch", ja: "校舎を切替" },
  "สิทธิ์ที่ผู้ถามมี: {0}": { en: "Permissions the asker has: {0}", ja: "質問者が持つ権限: {0}" },
  "สิทธิ์ที่ผู้ถามไม่มี: {0}": { en: "Permissions the asker doesn't have: {0}", ja: "質問者が持たない権限: {0}" },
  "ส่งสรุป": { en: "Send summaries", ja: "まとめを送信" },
  "ส่งให้ทีม": { en: "Send to team", ja: "チームに送信" },
  "หน้า Reports → เลือกหัวข้อ (ภาพรวม รายได้ นักเรียน การเข้าเรียน Operations CRM ความพึงพอใจ) และช่วงเวลา": { en: "Reports page → pick a topic (Overview, Revenue, Students, Attendance, Operations, CRM, Satisfaction) and a period", ja: "レポートページ → トピック（概要・売上・生徒・出席・オペレーション・CRM・満足度）と期間を選択" },
  "หน้าครอบครัว": { en: "Families page", ja: "家族ページ" },
  "หน้าคลาส": { en: "Classes page", ja: "クラスページ" },
  "หน้าคลาส › สร้างคลาส หรือกดช่องว่างในปฏิทิน → เลือกแบบคลาส (ครู + ช่วงเวลา / วิชา + ระดับชั้น) วัน เวลา ครู ห้อง · ระบบเช็คครู/ห้องชนและวันหยุดให้": { en: "Classes page › Create class, or click an empty slot in the calendar → pick the class type (teacher + time block / subject + grade), day, time, teacher, room · the system checks teacher / room clashes and holidays", ja: "クラスページ › クラスを作成、またはカレンダーの空き枠をクリック → クラスの種類（講師＋時間帯／科目＋学年）・曜日・時間・講師・教室を選択 · 講師・教室の重複と休日をシステムがチェック" },
  "หน้าคอร์ส": { en: "Courses page", ja: "コースページ" },
  "หน้าคอร์ส › สร้างคอร์ส → Single/Bundle, วิชา, ระดับชั้น, แพ็กเกจ (ชม. / สัปดาห์ / รายเดือน) ราคาดึงจากตารางราคาของสาขา · Max Student = จำนวนนักเรียนสูงสุดของทั้งคอร์ส": { en: "Courses page › Create course → Single/Bundle, subjects, grades, package (hours / weeks / monthly), price from the branch price chart · Max Student = the most students the whole course takes", ja: "コースページ › コースを作成 → Single/Bundle・科目・学年・パッケージ（時間・週・月）、価格は校舎の価格表から · Max Student = コース全体の定員" },
  "หน้านักเรียน": { en: "Students page", ja: "生徒ページ" },
  "หน้านักเรียน › ปุ่ม เพิ่มนักเรียน → กรอกชื่อ ชื่อเล่น ชั้น แล้วผูกครอบครัว · หรือเปิด Panel ครอบครัว › เพิ่มลูก (ผูกครอบครัวให้อัตโนมัติ)": { en: "Students page › Add student → name, nickname, grade, then link a family · or open the Family panel › Add child (links the family automatically)", ja: "生徒ページ › 生徒を追加 → 名前・ニックネーム・学年を入力し家族を連携 · または家族パネル › 子どもを追加（自動で家族に連携）" },
  "หน้าบุคลากร": { en: "Staff page", ja: "スタッフページ" },
  "หน้าบุคลากร › เพิ่มบุคลากร → ชื่อ บทบาทต่อสาขา (Manager / Admin / Teacher) วิชาที่สอน และเปิดบัญชีล็อกอินถ้าต้องการ": { en: "Staff page › Add staff → name, role per branch (Manager / Admin / Teacher), subjects taught, and a login if needed", ja: "スタッフページ › スタッフを追加 → 名前・校舎ごとの役職（Manager / Admin / Teacher）・担当科目、必要ならログインを開設" },
