  "ใบแจ้งหนี้ & รับเงิน › สร้างใบแจ้งหนี้ → เลือกนักเรียน + คอร์ส (+ ค่ารถ/ค่าแรกเข้า) → บันทึก (ออกเลขทันที) → สร้าง PDF → ให้อีกคนอนุมัติ → ส่งผู้ปกครองทาง LINE → บันทึกรับเงิน → อีกคนยืนยันยอด → ออกใบเสร็จ + เข้าคลาสอัตโนมัติ": { en: "Invoices & payments › Create invoice → pick student + course (+ bus / entry fee) → save (number issued now) → create PDF → someone else approves → send to the parent on LINE → record payment → someone else confirms the amount → receipt issued + into the class automatically", ja: "請求・入金 › 請求書を作成 → 生徒とコースを選択（＋送迎・入会金）→ 保存（番号を即発行）→ PDF作成 → 他の人が承認 → LINEで保護者に送信 → 入金を記録 → 他の人が金額確認 → 領収書発行＋自動でクラスに参加" },
